    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77", "C78", "C79", "C80"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or matched oral/IV exposure record for biperiden is present in the supplied cards.",
    "No biperiden-specific AUC, Cmax, dose, formulation, or human PK data are supplied.",
    "No biperiden-specific hepatic clearance or metabolic-stability measurement is supplied; L6 records are for other molecules.",
    "Trihexyphenidyl Caco-2 permeability/efflux is analog evidence, not a biperiden F measurement; first-pass metabolism and clinical F remain unmeasured.",
    "No affirmative F < 20% experimental evidence for biperiden is supplied; the high prediction rests on structural identification, physicochemical prior, and analog permeability."
  ],
  "decision_summary": "L6 adds no biperiden-specific hepatic clearance or metabolic-stability data; the records for loperamide, terfenadine, oxybutynin, fluphenazine, and others are not transferable as affirmative low-F evidence. The trihexyphenidyl Caco-2 permeability/efflux evidence remains supportive but indirect, and no affirmative F < 20% evidence appears, so the high prediction is retained at moderate confidence."
}

